def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)

    colors = {grid[r][c] for r, c in pts}
    border = grid[r0][c0]
    fill = next(x for x in colors if x != border)

    # Determine frame thickness from the top edge at the midpoint.
    midc = (c0 + c1) // 2
    t = 0
    while r0 + t <= r1 and grid[r0 + t][midc] == border:
        t += 1

    out = [row[:] for row in grid]
    for r in range(max(0, r0 - t), min(h, r1 + t + 1)):
        for c in range(max(0, c0 - t), min(w, c1 + t + 1)):
            if grid[r][c] == 0:
                out[r][c] = fill
    return out
